import logging
from typing import List

import torch

logger = logging.getLogger(__name__)


def unflatten(A: torch.Tensor, dim: int, sizes: List[int]) -> torch.Tensor:
    r"""Expand a single dimension of a tensor into multiple dimensions.

    This is the inverse operation of :func:`torch.flatten`.

    Args:
        A (torch.Tensor): Input tensor.
        dim (int): Dimension to unflatten.
        sizes (List[int]): New shape of the unflattened dimension.

    Returns:
        torch.Tensor: A view of the input tensor with the specified
            dimension unflattened.

    This op launches no kernel, so the whole cost is host-side dispatch. A
    fast path serves non-negative in-range dims with 2-element sizes that
    need no ``-1`` inference and already multiply up to the split dimension:
    logging, negative-dim normalization, ``-1`` inference and the error
    machinery run only on the cold path below. The result is always a
    zero-copy view built by ``A.view`` (shared storage, strides and storage
    offset unchanged), including for expanded / non-contiguous operands.
    """
    # Fast path: already-valid dims skip the debug log and the validation
    # machinery below and go straight to the metadata view. Passing a plain
    # tuple keeps ``view`` on its fastest argument-conversion path. The dim
    # range check runs first so negative dims bail out immediately.
    if (
        0 <= dim < A.ndim
        and type(sizes) is tuple
        and len(sizes) == 2
        and sizes[0] != -1
        and sizes[1] != -1
        and sizes[0] * sizes[1] == A.shape[dim]
    ):
        t = tuple(A.shape)
        if dim == 0:
            return A.view(sizes + t[1:])
        return A.view(t[:dim] + sizes + t[dim + 1 :])

    logger.debug("GEMS_ENFLAME unflatten")

    # Handle negative dim
    if dim < 0:
        dim += A.dim()

    # Validate that product of sizes matches the dimension size
    dim_size = A.size(dim)
    product = 1
    inferred_idx = -1
    for i, s in enumerate(sizes):
        if s == -1:
            if inferred_idx != -1:
                raise RuntimeError("only one dimension can be inferred")
            inferred_idx = i
        else:
            product *= s

    if inferred_idx != -1:
        if dim_size % product != 0:
            raise RuntimeError(
                f"inferred size {dim_size // product} is not a factor of "
                f"dimension size {dim_size}"
            )
        sizes = list(sizes)
        sizes[inferred_idx] = dim_size // product
    else:
        if product != dim_size:
            raise RuntimeError(
                f"unflatten: Provided sizes {sizes} don't multiply up to the "
                f"size of dim {dim} ({dim_size}) in the input tensor"
            )

    # Build new shape: shape[:dim] + sizes + shape[dim+1:]
    new_shape = list(A.shape[:dim]) + list(sizes) + list(A.shape[dim + 1 :])

    return A.view(new_shape)
